//! Database abstraction layer.//!//! Provides a backend-agnostic `Database` trait that unifies all persistence//! operations. Two implementations exist behind feature flags://!//! - `postgres` (default): Uses `deadpool-postgres` + `tokio-postgres`//! - `libsql`: Uses libSQL (Turso's SQLite fork) for embedded/edge deployment//!//! The existing `Store`, `Repository`, `SecretsStore`, and `WasmToolStore`//! types become thin wrappers that delegate to `Arc<dyn Database>`.#[cfg(feature = "postgres")]pub mod postgres;#[cfg(feature = "postgres")]pub mod tls;#[cfg(feature = "libsql")]pub mod libsql;#[cfg(feature = "libsql")]pub mod libsql_migrations;use std::collections::HashMap;use std::sync::Arc;use async_trait::async_trait;use chrono::{DateTime, Utc};use rust_decimal::Decimal;use uuid::Uuid;use crate::agent::BrokenTool;use crate::agent::routine::{Routine, RoutineRun, RunStatus};use crate::context::{ActionRecord, JobContext, JobState};use crate::error::DatabaseError;use crate::error::WorkspaceError;use crate::history::{    AgentJobRecord, AgentJobSummary, ConversationMessage, ConversationSummary, JobEventRecord,    LlmCallRecord, SandboxJobRecord, SandboxJobSummary, SettingRow,};use crate::workspace::{MemoryChunk, MemoryDocument, WorkspaceEntry};use crate::workspace::{SearchConfig, SearchResult};/// Create a database backend from configuration, run migrations, and return it.////// This is the shared helper for CLI commands and other call sites that need/// a simple `Arc<dyn Database>` without retaining backend-specific handles/// (e.g., `pg_pool` or `libsql_conn` for the secrets store). The main agent/// startup in `main.rs` uses its own initialization block because it also/// captures those backend-specific handles.